(107801, 4683, 2223, '<td valign="top">very pretty, good compositon</td>', 'very pretty, good compositon', '2002-08-19 01:42:00.000000', NULL, 1),
(107802, 4683, 674, '<td valign="top">Creative use of colour! Focus seems a little off though  giving the image a rather soft look. You may have intended this, still I like it. sulamk</td>', 'Creative use of colour! Focus seems a little off though  giving the image a rather soft look. You may have intended this, still I like it. sulamk', '2002-08-19 02:18:00.000000', NULL, 1),
