(108427, 4720, 2427, '<td valign="top">Good macro idea.</td>', 'Good macro idea.', '2002-08-21 17:47:00.000000', NULL, 1),
(108428, 4720, 2437, '<td valign="top">i love the concept</td>', 'i love the concept', '2002-08-22 02:51:00.000000', NULL, 1),
