(108656, 4731, 3198, '<td valign="top">jolly! that is a nice star</td>', 'jolly! that is a nice star', '2002-08-21 06:48:00.000000', NULL, 1),
(108657, 4731, 3220, '<td valign="top">some contrast or sharpening would have been nice.  but it was a great idea/concept.</td>', 'some contrast or sharpening would have been nice.  but it was a great idea/concept.', '2002-08-21 12:31:00.000000', NULL, 1),
(108658, 4731, 3087, '<td valign="top">I love the idea and composition of this, which is where it gets the score from. Technically I find it a little dark, could do with more light and more vibrancy of colour. Is the graininess deliberate affect? Wasn''t sure.<br/>6, Kavey<br/></td>', 'I love the idea and composition of this, which is where it gets the score from. Technically I find it a little dark, could do with more light and more vibrancy of colour. Is the graininess deliberate affect? Wasn''t sure.6, Kavey', '2002-08-21 20:03:00.000000', NULL, 1),
(108659, 4731, 2427, '<td valign="top">neat pencil trick</td>', 'neat pencil trick', '2002-08-22 01:07:00.000000', NULL, 1),
(108660, 4731, 2667, '<td valign="top">i like this shot. i think it is very elegant and well composed. (6)   ~mcmurma</td>', 'i like this shot. i think it is very elegant and well composed. (6)   ~mcmurma', '2002-08-22 02:48:00.000000', NULL, 1),
