INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(109030, 4753, 1202, '<td valign="top">Composition: Subject Placement, Cropping, Background8,<br/>Technical: Focus, Exposure, Lighting, Processing7,<br/>Challenge: Does your entry meet it?10,<br/>Appeal: Is it Interesting, Motivating, Etc.? 6,<br/>Total Averaged Rating8.   Autool<br/></td>', 'Composition: Subject Placement, Cropping, Background8,Technical: Focus, Exposure, Lighting, Processing7,Challenge: Does your entry meet it?10,Appeal: Is it Interesting, Motivating, Etc.? 6,Total Averaged Rating8.   Autool', '2002-08-21 23:42:00.000000', NULL, 1),
(109031, 4753, 3080, '<td valign="top">Pencils.  Definately a lot of pencils.  Great photo.  You captured the flame nicely.  You wouldn''t want to see my attempt at photographing fire.  I like how the pencils are lined up.  repetition always catches my eye.  lighting is good.  there might be a tad bit of glare on the erasers in the front, but not enough to really distract from the photo.  overall a great job.  Good luck in the challenge.</td>', 'Pencils.  Definately a lot of pencils.  Great photo.  You captured the flame nicely.  You wouldn''t want to see my attempt at photographing fire.  I like how the pencils are lined up.  repetition always catches my eye.  lighting is good.  there might be a tad bit of glare on the erasers in the front, but not enough to really distract from the photo.  overall a great job.  Good luck in the challenge.', '2002-08-22 14:35:00.000000', NULL, 1),
(109032, 4753, 1856, '<td valign="top">Great idea!  I almost wish this were zoomed out a bit so you could see more of the structure.  Original.  Lisa</td>', 'Great idea!  I almost wish this were zoomed out a bit so you could see more of the structure.  Original.  Lisa', '2002-08-23 23:08:00.000000', NULL, 1),
(109033, 4753, 835, '<td valign="top">i''m curious to know what all of the pencils are too stay so packed together. I like the lighting as it is but I would prefer slightly better focus on the front pencils.  neat idea</td>', 'i''m curious to know what all of the pencils are too stay so packed together. I like the lighting as it is but I would prefer slightly better focus on the front pencils.  neat idea', '2002-08-24 00:15:00.000000', NULL, 1),
(109034, 4754, 3226, '<td valign="top">ancient stylus</td>', 'ancient stylus', '2002-08-19 15:00:00.000000', NULL, 1),
(109035, 4754, 472, '<td valign="top">good close up but the keys are dark.. maybe a side light to illuminate their vertical edges.</td>', 'good close up but the keys are dark.. maybe a side light to illuminate their vertical edges.', '2002-08-19 21:48:00.000000', NULL, 1),
(109036, 4754, 3099, '<td valign="top">Seems a bit boring to me...</td>', 'Seems a bit boring to me...', '2002-08-20 09:28:00.000000', NULL, 1),
