(109628, 4787, 2158, '<td valign="top">One of the few I''ve seen where the shallow depth of field works in its favour.  well done.</td>', 'One of the few I''ve seen where the shallow depth of field works in its favour.  well done.', '2002-08-22 22:35:00.000000', NULL, 1),
(109629, 4787, 1856, '<td valign="top">good composition and lighting...i wish the entire pencil had been in focus though</td>', 'good composition and lighting...i wish the entire pencil had been in focus though', '2002-08-23 23:55:00.000000', NULL, 1),
(109630, 4787, 1042, '<td valign="top">simple..and very nicely done in it''s simplicity. 9</td>', 'simple..and very nicely done in it''s simplicity. 9', '2002-08-25 23:55:00.000000', NULL, 1),
